// MigrationStrategy picks the cutover algorithm. Strategies trade off
// blast-radius vs duration vs operator-touch.
type MigrationStrategy int32

const (
	MigrationStrategy_MIGRATION_STRATEGY_UNSPECIFIED MigrationStrategy = 0
	// Default. New flows go to target as soon as READY; source DPU drains
	// existing flows to age-out. Lowest blast radius, longest duration.
	MigrationStrategy_MIGRATION_STRATEGY_NEW_FLOWS_FIRST_DRAIN MigrationStrategy = 1
	// Full re-home: all flows are synced before cutover, then source goes
	// cold immediately. Fastest cutover but biggest sync cost.
	MigrationStrategy_MIGRATION_STRATEGY_FULL_REHOME MigrationStrategy = 2
	// Maintenance-fast: skip sync, accept brief connection reset for live
	// flows. Use only when downtime tolerance is high.
	MigrationStrategy_MIGRATION_STRATEGY_MAINTENANCE_FAST MigrationStrategy = 3
	// Canary split: traffic is divided between source and target at CUTOVER
	// with progressive shift. Requires operator-driven phase advance per
	// increment.
	MigrationStrategy_MIGRATION_STRATEGY_CANARY_SPLIT MigrationStrategy = 4
)

